def column_totals(rows):
    if not rows:
        return []
    result = []
    for i in range(len(rows[0])):
        col_values = [r[i] for r in rows]
        numeric_values = []
        for val in col_values:
            try:
                num = float(val)
                numeric_values.append(num)
            except (ValueError, TypeError):
                continue
        if numeric_values:
            total = sum(numeric_values)
            result.append(total)
        else:
            result.append("")
    return result

